import{U as e,W as t,j as n,nt as r}from"./chunks/framework.HOVv_sfg.js";var i=JSON.parse(`{"title":"Telemann-Werke-Verzeichnis","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"pages/catalogues/twv.md","filePath":"pages/catalogues/twv.md"}`),a={name:`pages/catalogues/twv.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="telemann-werke-verzeichnis" tabindex="-1">Telemann-Werke-Verzeichnis <a class="header-anchor" href="#telemann-werke-verzeichnis" aria-label="Permalink to “Telemann-Werke-Verzeichnis”">​</a></h1><p>The <em>Telemann-Werke-Verzeichnis</em> (TWV) is the catalogue of the works of Georg Philipp Telemann.</p><h2 id="about-the-catalogue" tabindex="-1">About the Catalogue <a class="header-anchor" href="#about-the-catalogue" aria-label="Permalink to “About the Catalogue”">​</a></h2><p>The TWV catalogue provides a systematic numbering system for identifying the works of Georg Philipp Telemann. It was compiled by Werner Menke and first published between 1941 and 1951.</p><table tabindex="0"><thead><tr><th>Property</th><th>Information</th></tr></thead><tbody><tr><td>Abbreviation</td><td>TWV</td></tr><tr><td>Composer</td><td>Georg Philipp Telemann</td></tr><tr><td>Compiler</td><td>Werner Menke</td></tr><tr><td>Catalogue type</td><td>Work catalogue</td></tr><tr><td>First published</td><td>1941–1951</td></tr></tbody></table><h2 id="catalogue-sections" tabindex="-1">Catalogue Sections <a class="header-anchor" href="#catalogue-sections" aria-label="Permalink to “Catalogue Sections”">​</a></h2><p>The TWV catalogue is organized into several major sections according to genre and type of composition.</p><table tabindex="0"><thead><tr><th>TWV Range</th><th>Category</th></tr></thead><tbody><tr><td>TWV 1 – TWV 15</td><td>Sacred vocal music</td></tr><tr><td>TWV 20 – TWV 25</td><td>Secular vocal music</td></tr><tr><td>TWV 30 – TWV 39</td><td>Music for keyboard instruments and lute</td></tr><tr><td>TWV 40 – TWV 45</td><td>Chamber music</td></tr><tr><td>TWV 50 – TWV 55</td><td>Orchestral music</td></tr></tbody></table><h3 id="sacred-vocal-music" tabindex="-1">Sacred Vocal Music <a class="header-anchor" href="#sacred-vocal-music" aria-label="Permalink to “Sacred Vocal Music”">​</a></h3><p><strong>TWV 1 – TWV 15</strong></p><p>Sacred vocal works, including church cantatas, oratorios, passions, and other liturgical and devotional compositions.</p><h3 id="secular-vocal-music" tabindex="-1">Secular Vocal Music <a class="header-anchor" href="#secular-vocal-music" aria-label="Permalink to “Secular Vocal Music”">​</a></h3><p><strong>TWV 20 – TWV 25</strong></p><p>Secular vocal works, including operas, serenatas, odes, and other dramatic or occasional compositions.</p><h3 id="keyboard-and-lute-music" tabindex="-1">Keyboard and Lute Music <a class="header-anchor" href="#keyboard-and-lute-music" aria-label="Permalink to “Keyboard and Lute Music”">​</a></h3><p><strong>TWV 30 – TWV 39</strong></p><p>Works for keyboard instruments and lute, including compositions for harpsichord, organ, and related instruments.</p><h3 id="chamber-music" tabindex="-1">Chamber Music <a class="header-anchor" href="#chamber-music" aria-label="Permalink to “Chamber Music”">​</a></h3><p><strong>TWV 40 – TWV 45</strong></p><p>Chamber music, including sonatas, trios, quartets, and other instrumental ensemble works.</p><h3 id="orchestral-music" tabindex="-1">Orchestral Music <a class="header-anchor" href="#orchestral-music" aria-label="Permalink to “Orchestral Music”">​</a></h3><p><strong>TWV 50 – TWV 55</strong></p><p>Orchestral works, including overtures, suites, concertos, and other works for orchestra.</p><h2 id="key-designations" tabindex="-1">Key Designations <a class="header-anchor" href="#key-designations" aria-label="Permalink to “Key Designations”">​</a></h2><p>In TWV numbers, uppercase and lowercase letters indicate the major or minor mode of the work.</p><table tabindex="0"><thead><tr><th>Designation</th><th>Meaning</th></tr></thead><tbody><tr><td>Uppercase</td><td>Major</td></tr><tr><td>Lowercase</td><td>Minor</td></tr></tbody></table><p>For example:</p><table tabindex="0"><thead><tr><th>TWV</th><th>Key</th></tr></thead><tbody><tr><td>TWV 51:D1</td><td>D major</td></tr><tr><td>TWV 51:d1</td><td>D minor</td></tr><tr><td>TWV 52:A2</td><td>A major</td></tr><tr><td>TWV 52:a2</td><td>A minor</td></tr><tr><td>TWV 55:e3</td><td>E minor</td></tr></tbody></table><p>The letter is followed by a number that distinguishes individual works within the same catalogue category and key.</p><h2 id="numbering-system" tabindex="-1">Numbering System <a class="header-anchor" href="#numbering-system" aria-label="Permalink to “Numbering System”">​</a></h2><p>A TWV number generally consists of several components:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>TWV 52:a1</span></span>
<span class="line"><span>│   │  │</span></span>
<span class="line"><span>│   │  └── Individual work number</span></span>
<span class="line"><span>│   └───── Key designation</span></span>
<span class="line"><span>└───────── Catalogue category</span></span></code></pre></div>`,32)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};